-- Free text: boss descriptions and notes, ability fight texts, phase/extra titles, quest text.
L.STRINGS = {
	-- Boss notes (the strings inside `notes = { ... }` in the data files).
	["A Blackrock orc who can be found in one of four cells."] = "Орк Черной горы, которого можно найти в одной из четырёх камер.",
	["A Dark Iron dwarf held for his part in the Thandol Span attacks."] = "Дворф Темного Железа, схваченный за участие в нападениях на Танадольский мост.",
	["A fallen paladin who heals himself and shields himself from harm."] = "Павший паладин, который лечит себя и укрывается от урона щитом.",
	["A Fanglord who turns into a serpent partway through the fight."] = "Повелитель Клыка, который в середине боя превращается в змея.",
	["A felguard standing in the middle of the lava lake, and the hardest-hitting boss here."] = "Скверностраж посреди лавового озера — самый бьющий босс здесь.",
	["A giant turtle in the first great pool."] = "Гигантская черепаха в первом большом пруду.",
	["A giant turtle that will not attack first; killing him is optional."] = "Гигантская черепаха, которая не нападает первой; убивать её необязательно.",
	["A hidden boss you summon. Take the Black Tome from Archmage Arugal's table in Shadowfang Keep after his kill, and turn it into the Tome of Dalaran at the Leyline Focus, a blue crystal in a back room at Ambermill in Silverpine Forest."] = "Скрытый босс, которого вы призываете сами. Возьмите Чёрный фолиант со стола архимага Аругала в Крепости Темного Клыка после его убийства и превратите его в «Фолиант Даларана» у Лей-фокуса — синего кристалла в дальней комнате в Янтарной мельнице в Серебряном бору.",
	["A mage or a druid can remove his Call of the Grave before it goes off. He fears, and drains two players below half health."] = "Маг или друид может снять его «Зов могилы» до срабатывания. Он пугает и вытягивает жизнь у двух игроков ниже половины здоровья.",
	["A magic dispel removes his Shadow Word: Pain."] = "Магическое рассеивание снимает его «Слово Тьмы: Боль».",
	["A massive plant creature; optional."] = "Огромное растение; необязательный противник.",
	["A murloc chieftain in his shrine. His followers run for help when they are low on health, so finish them off."] = "Мурлок-вождь в своём святилище. Его последователи убегают за помощью, когда у них мало здоровья, так что добивайте их.",
	["A naga sorceress in a side cavern off the pool; optional."] = "Нага-колдунья в боковой пещере у пруда; необязательный противник.",
	["A priest or a shaman can remove his Bloodlust."] = "Жрец или шаман может снять его «Жажду крови».",
	["A rare bat in a small recess of the bat cave near Charlga Razorflank: not every run meets it."] = "Редкая летучая мышь в небольшой нише пещеры летучих мышей рядом с Чарлгой Остробок: есть не в каждом заходе.",
	["A rare spawn with two possible locations: not every run meets him."] = "Редкое появление в двух возможных местах: есть не в каждом заходе.",
	["A rare spawn: not every run meets him."] = "Редкое появление: есть не в каждом заходе.",
	["A rare spawn: not every run meets him. At 15% health he runs for help."] = "Редкое появление: есть не в каждом заходе. На 15% здоровья убегает за помощью.",
	["A rare. A Stone Rumbler fights with him; interrupt his Lightning Bolt, and finish him before he runs for help at 15% health."] = "Редкий. С ним сражается Каменный грохотун; прерывайте его «Молнию» и добейте его до того, как он убежит за помощью на 15% здоровья.",
	["A rare. He calls two Burning Servants; interrupt his Fireball, and a priest or a shaman can remove his fire shield."] = "Редкий. Он призывает двух пылающих слуг; прерывайте его «Огненный шар», а жрец или шаман может снять его огненный щит.",
	["A rare. He cuts the tank's armour by three quarters, and at 15% health runs for help: finish him first."] = "Редкий. Срезает броню танка на три четверти, а на 15% здоровья убегает за помощью: добейте его первым.",
	["A satyr on the walkway above Jergosh's chamber."] = "Сатир на помосте над залом Джергоша.",
	["A Searing Blade warlock; clear the cultists around him first."] = "Чернокнижник Раскалённого Клинка; сначала зачистите культистов вокруг него.",
	["A Stone Rumbler fights at his side; interrupt his Lightning Bolt."] = "Каменный грохотун сражается рядом с ним; прерывайте его «Молнию».",
	["A test of the tank: he hits hard, disarms, and his Unholy Frenzy speeds his attacks by 75% for 20 seconds. Purge or dispel the frenzy, and tanks should bring a shield."] = "Испытание для танка: он бьёт больно, обезоруживает, а его «Нечестивое бешенство» ускоряет атаки на 75% на 20 секунд. Снимите бешенство «Очищением» или рассеиванием; танкам стоит взять щит.",
	["A threshadon in the underwater cave; optional. He only melees."] = "Трэшодон в подводной пещере; необязательный противник. Он бьёт только в ближнем бою.",
	["A thunder lizard in the water; killing him is optional."] = "Громовой ящер в воде; убивать его необязательно.",
	["A trogg brute on the main path; a straightforward fight if no other packs join in."] = "Трогг-громила на главном пути; простой бой, если не подойдут другие группы.",
	["A Twilight's Hammer shaman patrolling the tunnels."] = "Шаман Молота Сумерек, патрулирующий туннели.",
	["A ward seals his cave: kill the two Death's Head Ward Keepers in front of it to bring it down."] = "Пещеру закрывает оберег: убейте двух Хранителей оберега Мёртвой Головы перед ним, чтобы снять его.",
	["Acid Splash hurts everyone near him over time. Interrupt his heal below half health; at 15% he runs for help."] = "«Всплеск кислоты» со временем бьёт всех рядом. Прерывайте его исцеление ниже половины здоровья; на 15% он убегает за помощью.",
	["After the fight, open the room's vaults: about 24 Dwarven Heirlooms for Important Heirlooms, and the stone tablet that starts The Treaty of Understanding."] = "После боя откройте хранилища комнаты: около 24 дворфийских реликвий для «Важных реликвий» и каменную табличку, с которой начинается «Договор о взаимопонимании».",
	["An ogre foreman with heavy armour who hits hard; the first boss inside."] = "Огр-бригадир в тяжёлой броне, бьёт больно; первый босс внутри.",
	["An ogre who throws lightning that jumps between players."] = "Огр, который мечет молнию, перескакивающую между игроками.",
	["Angry Tomes come out of the buildings as you approach: clear them before the fight."] = "При приближении из зданий вылетают Злые фолианты: зачистите их до боя.",
	["Anti-Magic Shield guards him against spells for a while, and he hits hard: keep the tank topped up."] = "«Щит от магии» на время защищает его от заклинаний, и он бьёт больно: держите танка на полном здоровье.",
	["Arrives with three goblin helpers."] = "Приходит с тремя гоблинскими помощниками.",
	["Arugal's Curse turns a player into a worgen who attacks their own group."] = "«Проклятие Аругала» превращает игрока в воргена, который нападает на свою группу.",
	["At 66% and again at 33% health he stomps, stunning everyone around him, then walks to his chest to change weapons."] = "На 66%, а затем на 33% здоровья он топает, оглушая всех вокруг, затем идёт к сундуку менять оружие.",
	["At half health Divine Shield makes him immune for 12 seconds. He stuns with Hammer of Justice, and his aura hurts whoever strikes him in melee."] = "На половине здоровья «Божественный щит» делает его неуязвимым на 12 секунд. Он оглушает «Молотом правосудия», а его аура ранит тех, кто бьёт его в ближнем бою.",
	["At half health she puts the room to sleep and raises Mograine, who heals her fully: the two fight together."] = "На половине здоровья она усыпляет комнату и поднимает Могрейна, который полностью её лечит: они сражаются вдвоём.",
	["At low health he fears the whole group: clear the room first, and bring a way to break fear."] = "При низком здоровье он пугает всю группу: сначала зачистите комнату и возьмите способ снять страх.",
	["At the ritual circle in the sewers, with Kirin Tor Necromancers around him."] = "У ритуального круга в канализации, вокруг него — некроманты Кирин-Тора.",
	["Below 30% health he attacks faster for the rest of the fight."] = "Ниже 30% здоровья он атакует быстрее до конца боя.",
	["Below half health the faces come faster, and his Knock Away hits everyone around him."] = "Ниже половины здоровья лики срабатывают быстрее, а его «Отбрасывание» бьёт всех вокруг.",
	["Bounding Mana flies to a player and back, silencing anyone it passes through: don't stand between him and its target. Casters stay 20 yards away from his Arcane Explosion."] = "«Скачущая мана» летит к игроку и обратно, лишая безмолвия всех, сквозь кого пройдёт: не стойте между ним и целью сферы. Заклинателям держаться в 20 метрах от его «Магического взрыва».",
	["By the entrance to the Violet Hold. Clear his room first: anything still alive in it joins the fight."] = "У входа в Фиолетовую крепость. Сначала зачистите его комнату: всё живое в ней присоединится к бою.",
	["Changes weapons partway through the fight."] = "В середине боя меняет оружие.",
	["Clear his room before the pull: a patrol walks by. His head is looted for Abominable Creatures and Unending Torment."] = "Зачистите его комнату перед пулом: мимо ходит патруль. Его голову снимают для «Омерзительных созданий» и «Нескончаемых мук».",
	["Clear the courtyard, click the statue and survive the waves: she comes after them."] = "Зачистите двор, нажмите на статую и переживите волны: она приходит после них.",
	["Clear the cultists around him one group at a time before pulling him."] = "Зачистите культистов вокруг него по одной группе, прежде чем пулить.",
	["Clear the house and the statue, click the fireplace and survive the waves: he comes after the last flesh golem."] = "Зачистите дом и статую, нажмите на камин и переживите волны: он приходит после последнего мясного голема.",
	["Click the Fathom Stone in the water and he rises from it. He casts Frostbolt from range, and Frost Nova roots those near him."] = "Нажмите на Глубинный камень в воде, и он поднимется из него. Он применяет «Ледяную стрелу» с расстояния, а «Кольцо льда» обездвиживает всех рядом с ним.",
	["Crowd Pummel hits and interrupts everyone near it: casters and healers, keep away. It also smashes in a cone and tramples."] = "«Избиение толпы» бьёт и прерывает всех рядом: заклинателям и лекарям держаться подальше. Оно также бьёт в конусе и топчет.",
	["Cure his poison, which also drains mana."] = "Снимите его яд, который также вытягивает ману.",
	["Cure the poison of his harpoon; his Cleave hits beside the tank."] = "Снимите яд от его гарпуна; его «Раскол» бьёт рядом с танком.",
	["Curses and diseases: bring a way to remove them. Otherwise an easy fight; clear the room before the pull."] = "Проклятия и болезни: возьмите способ их снимать. В остальном бой лёгкий; зачистите комнату перед пулом.",
	["Dalaran"] = "Даларан",
	["Debilitate drains mana from everyone within 45 yards, and Drain Vitality wears down the tank: dispel it. A race before your mana runs out. He is immune to arcane."] = "«Истощение» вытягивает ману у всех в радиусе 45 метров, а «Высасывание жизненных сил» изматывает танка: рассеять. Гонка, пока не кончилась мана. Он невосприимчив к тайной магии.",
	["Defeating him opens the door onward."] = "Победа над ним открывает дверь дальше.",
	["Drops the Horrible Rootcore for Horrors in the Highland."] = "Роняет Ужасное корневище для «Ужасов высокогорья».",
	["Drops the Titan Relic that starts each side's relic quest."] = "Роняет титаническую реликвию, с которой начинается задание о реликвии у каждой фракции.",
	["Entangle roots up to two players near him and hurts them: dispel it. Fel Timbers leaves poisonous pools: anyone rooted in one needs Blessing of Freedom or Escape Artist."] = "«Запутывание» обездвиживает до двух игроков рядом и наносит им урон: рассеять. «Дрова Скверны» оставляют ядовитые лужи: тому, кого в них обездвижило, нужны «Благословение свободы» или «Мастер побега».",
	["Every 15 to 25 seconds he whirls for 10 seconds, hitting everyone near him: melee, step back until it ends."] = "Каждые 15–25 секунд он вращается 10 секунд, бьёт всех рядом: ближнему бою отойти, пока это не закончится.",
	["Fire Nova burns everyone near him several times a fight: healers, keep the melee topped up."] = "«Огненная вспышка» жжёт всех рядом несколько раз за бой: лекари, держите ближний бой на полном здоровье.",
	["Flamestrike is his main spell, and he can be interrupted and stunned: plan your kicks and stuns."] = "«Огненный столб» — его основное заклинание, его можно прерывать и оглушать: планируйте сбивания и станы.",
	["Focal Blast: after a 3-second cast, a beam sweeps around the room, turning counterclockwise, for 6 seconds. Get out of its path as the cast starts: it kills."] = "«Фокальный залп»: после применения 3 сек. луч 6 секунд описывает круг по комнате против часовой стрелки. Уйдите с его пути, как только начнётся применение: это убивает.",
	["Four come once Fenrus the Devourer dies, called by Arugal. They heal each other: bring them down one at a time."] = "Четверо приходят после смерти Фенруса Пожирателя, призванные Аругалом. Они лечат друг друга: убивайте их по одному.",
	["Frost Nova hits the whole group: healers, pace your mana through the waves."] = "«Кольцо льда» бьёт всю группу: лекари, рассчитывайте ману между волнами.",
	["Guard the Disciple through waves of serpents and then oozes; Mutanus surfaces right after the oozes."] = "Защищайте Ученика через волны змей, а затем слизней; Мутанус появляется сразу после слизней.",
	["He calls everything within 15 yards, his two Razorfen Spearhides among them: crowd-control one. Thunderclap every 8 to 14 seconds slows those near him."] = "Он созывает всех в радиусе 15 метров, включая двух своих Копьеносцев Иглошкурых: возьмите одного под контроль. «Удар грома» каждые 8–14 секунд замедляет всех рядом.",
	["He can be at one of four places. A priest or a shaman can remove his Lightning Shield; interrupt his Lightning Bolt."] = "Он может быть в одном из четырёх мест. Жрец или шаман может снять его «Щит молний»; прерывайте его «Молнию».",
	["He cleaves, and at 30% health enrages for 2 minutes: much faster and harder blows."] = "Он бьёт «Расколом», а на 30% здоровья впадает в ярость на 2 минуты: удары намного быстрее и сильнее.",
	["He cleaves, and slows his target."] = "Он бьёт «Расколом» и замедляет свою цель.",
	["He cleaves, and strikes hard at a target below 20% health: keep the tank above it."] = "Он бьёт «Расколом» и сильно бьёт цель с менее 20% здоровья: держите танка выше.",
	["He disarms the tank."] = "Он обезоруживает танка.",
	["He drains mana from his target: a tank who uses mana feels it."] = "Он вытягивает ману у своей цели: танк, использующий ману, это почувствует.",
	["He drops his threat and changes target during the fight: damage dealers, ease off when the tank loses him; tank, take him back at once."] = "В бою он сбрасывает угрозу и меняет цель: бойцы, сбавьте обороты, когда танк теряет его; танк, сразу верните его.",
	["He fears the tank several times: a shaman's Tremor Totem helps."] = "Он несколько раз пугает танка: помогает тотем трепета шамана.",
	["He hurls the tank into the air, stunned for 5 seconds: damage dealers, watch your threat, the tank holds him only about half the fight."] = "Он подбрасывает танка в воздух и оглушает на 5 секунд: бойцы, следите за угрозой, танк держит его лишь около половины боя.",
	["He keeps calling Arcane Manalings: cleave them down."] = "Он постоянно призывает магических маналингов: сносите их «Расколом».",
	["He knocks players across the room: clear the packs nearest him, and tank him by the tunnel so nobody lands in another pack."] = "Он отбрасывает игроков по комнате: зачистите ближайшие группы и ведите его к туннелю, чтобы никто не угодил в другую группу.",
	["He knocks players back: clear the packs around him first, or you land in one."] = "Он отбрасывает игроков: сначала зачистите группы вокруг, иначе приземлитесь в одной из них.",
	["He leaves a player for dead (moving ends it), stuns everyone near him, and enrages at 60% and again at 40% health."] = "Он оставляет игрока умирать (движение прекращает это), оглушает всех рядом и впадает в ярость на 60%, а затем на 40% здоровья.",
	["He lies on the floor of the small room beside the altar, as if dead, and rises when attacked."] = "Он лежит на полу маленькой комнаты у алтаря, как мёртвый, и встаёт, когда его атакуют.",
	["He nets a player in place."] = "Он сажает игрока в сеть на месте.",
	["He poisons his target and hits hard. Bring mana potions for the waves before him."] = "Он отравляет свою цель и бьёт больно. Возьмите зелья маны для волн перед ним.",
	["He puts everyone near him to sleep (damage wakes a sleeper), and casts Mind Blast."] = "Он усыпляет всех рядом (урон будит спящего) и применяет «Взрыв разума».",
	["He roams the marsh near the start among elite crocolisks: clear them first, or pull him away from them."] = "В начале он бродит по болоту среди элитных кроколисков: убейте их первыми или уведите его от них.",
	["He stands in a Dragonmaw camp. Its groups pull apart easily: take them one at a time first. The fight itself is short."] = "Он стоит в лагере Драконьей Пасти. Их группы легко разделяются: сначала разбейте их по одной. Сам бой короткий.",
	["He summons a Boar Spirit every 30 to 45 seconds: kill each before the next comes. Below 75% health, interrupt his Chain Heal."] = "Каждые 30–45 секунд он призывает духа вепря: убивайте каждого до появления следующего. Ниже 75% здоровья прерывайте его «Цепное исцеление».",
	["He switches on the gnome faces around the room one by one, each sending out Walking Bombs: press the button beside a face to switch it off."] = "Он по очереди включает гномьи лики вокруг комнаты, и каждый выпускает Ходячие бомбы: нажмите кнопку рядом с ликом, чтобы выключить его.",
	["He tramples everyone standing close."] = "Он топчет всех, кто стоит рядом.",
	["He waits behind a barrier in the middle of the city. Kill the Suffused Treants in front of it, then speak to Magus Fansy Goodbringer, just south of the barrier, to bring it down."] = "Он ждёт за барьером в центре города. Убейте Насыщенных древней перед ним, затем поговорите с магусом Фэнси Добротворцем к югу от барьера, чтобы снять его.",
	["He waits in an underwater cave below Twilight Lord Kelris's temple: swim under the temple to find him."] = "Он ждёт в подводной пещере под храмом сумеречного лорда Келриса: проплывите под храмом, чтобы найти его.",
	["His Arcane Explosion hits everyone close to him, and Detonation hits harder still: keep your distance when he readies it."] = "Его «Магический взрыв» бьёт всех рядом, а «Детонация» ещё сильнее: держитесь подальше, когда он её готовит.",
	["His blows poison: cure it if you can. Sinister Strike adds damage on the tank."] = "Его удары отравляют: снимите яд, если можете. «Коварный удар» добавляет урона по танку.",
	["His Cleave also hits the player nearest his target: stand apart from the tank."] = "Его «Раскол» бьёт также ближайшего к цели игрока: стойте в стороне от танка.",
	["His Curse of Weakness reaches everyone within 30 yards (a mage or a druid can remove it), and he leaves a poison cloud."] = "Его «Проклятие слабости» достаёт всех в радиусе 30 метров (маг или друид может снять его), и он оставляет облако яда.",
	["His fire hits the whole group, and harder the more of you fight in melee."] = "Его огонь бьёт всю группу, и сильнее, чем больше вас бьёт в ближнем бою.",
	["His Scarlet Tracking Hounds fight beside him: kill them first. He uses Bloodlust."] = "Его Гончие Алого ордена сражаются рядом: убейте их первыми. Он применяет «Жажду крови».",
	["His shout sends nearby players fleeing in fear."] = "Его крик обращает игроков рядом в бегство от страха.",
	["His Slam stuns the tank for 3 seconds."] = "Его «Удар» оглушает танка на 3 секунды.",
	["His Smoke Bomb stuns everyone near him; at 15% health he runs for help."] = "Его «Дымовая бомба» оглушает всех рядом; на 15% здоровья он убегает за помощью.",
	["His Uppercut can throw a player back into lava or into nearby enemies."] = "Его «Апперкот» может отбросить игрока обратно в лаву или в ближайших врагов.",
	["Holds the top of the ship with two of his crew."] = "Держит верх корабля вместе с двумя членами экипажа.",
	["Interrupt her Chain Bolt. Every so often she is immune for 2 seconds, and a priest or a shaman can remove her Renew."] = "Прерывайте её «Цепную стрелу». Время от времени она неуязвима 2 секунды, а жрец или шаман может снять её «Обновление».",
	["Interrupt her Holy Smite and her heals; a priest or a shaman can remove her shield."] = "Прерывайте её «Святую кару» и исцеления; жрец или шаман может снять её щит.",
	["Interrupt his Chain Lightning. A priest or a shaman can remove his Bloodlust."] = "Прерывайте его «Цепную молнию». Жрец или шаман может снять его «Жажду крови».",
	["Interrupt his Chained Bolt, which jumps to a second player."] = "Прерывайте его «Окованную стрелу», которая перескакивает на второго игрока.",
	["Interrupt his Fear and, at 30% health, his heal. He puts everyone near him to sleep (damage wakes a sleeper), and a mage or a druid can remove his Curse of Blood."] = "Прерывайте его «Страх», а на 30% здоровья — его исцеление. Он усыпляет всех рядом (урон будит спящего), а маг или друид может снять его «Проклятие крови».",
	["Interrupt his Healing Touch. Thunderclap slows everyone near him."] = "Прерывайте его «Целебное прикосновение». «Удар грома» замедляет всех рядом.",
	["Interrupt his Holy Light. Divine Shield makes him immune for 10 seconds, and he stuns with Hammer of Justice."] = "Прерывайте его «Свет небес». «Божественный щит» делает его неуязвимым на 10 секунд, и он оглушает «Молотом правосудия».",
	["Interrupt his Immolate or dispel the burn. A mage or a druid can remove his Curse of Weakness."] = "Прерывайте его «Жертвенный огонь» или рассеивайте горение. Маг или друид может снять его «Проклятие слабости».",
	["Interrupt his Lightning Bolt and Healing Touch. Below 30% health his serpent form hits harder and puts players to sleep."] = "Прерывайте его «Молнию» и «Целебное прикосновение». Ниже 30% здоровья его змеиная форма бьёт сильнее и усыпляет игроков.",
	["Interrupt his Molten Metal, which burns and slows."] = "Прерывайте его «Расплавленный металл», который жжёт и замедляет.",
	["Interrupt his slow Healing Touch and his Lightning Bolt."] = "Прерывайте его медленное «Целебное прикосновение» и его «Молнию».",
	["Interrupt his Void Bolt. He teleports between his ledges, and stuns everyone around him when the tank reaches him."] = "Прерывайте его «Стрелу Бездны». Он телепортируется между выступами и оглушает всех вокруг, когда танк доходит до него.",
	["Interrupt or dispel his Dominate Mind, which takes over a player; interrupt his Shadow Bolt."] = "Прерывайте или рассеивайте его «Порабощение разума», которое подчиняет игрока; прерывайте его «Стрелу Тьмы».",
	["Interrupt or dispel his Polymorph. His Silence reaches 15 yards: healers, stand back."] = "Прерывайте или рассеивайте его «Превращение». Его «Безмолвие» достаёт на 15 метров: лекарям встать дальше.",
	["Interrupt or dispel his Soul Drain, which roots a player and drains their health."] = "Прерывайте или рассеивайте его «Вытягивание души», которое обездвиживает игрока и вытягивает его здоровье.",
	["It fears a player and slows another's casting."] = "Он пугает одного игрока и замедляет чтение заклинаний другого.",
	["It roots everyone near it, slows and stuns, and calls Dupe Bugs that its Patch turns into healing."] = "Оно обездвиживает всех рядом, замедляет и оглушает, а также призывает багов-двойников, которых его «Заплатка» превращает в исцеление.",
	["It whirls at everyone close, and its thorns hurt whoever strikes it or an ally nearby, Ramtusk included."] = "Оно вращается, бьёт всех рядом, а его шипы ранят того, кто бьёт его или союзника поблизости, включая Рамтаска.",
	["Kill the Dark Iron Summoner first: he keeps bringing adds. Then turn on the elemental."] = "Сначала убейте призывателя Темного Железа: он постоянно приводит подмогу. Затем займитесь элементалем.",
	["Kill the raptor matriarch in the tall grass. Her death brings a wave of raptors, and Shadetooth comes once they are dead: finish the whole wave before he arrives."] = "Убейте матриарха ящеров в высокой траве. Её смерть приводит волну ящеров, а когда они мертвы, приходит Сухоклык: добейте всю волну до его появления.",
	["Malfunction winds up for 2 seconds, then hits everyone within 25 yards every 2 seconds for 6 seconds: ranged stay beyond 25 yards, melee step out as the cast starts."] = "«Неисправность» готовится 2 секунды, затем 6 секунд бьёт всех в радиусе 25 метров каждые 2 секунды: стрелкам держаться дальше 25 метров, ближнему бою выйти, как только начнётся применение.",
	["Manamorph takes a player out of the fight for 8 seconds: dispel it. His Silence hits those close to him, so healers keep their distance."] = "«Манаморф» выводит игрока из боя на 8 секунд: рассеять. Его «Безмолвие» бьёт всех рядом, так что лекарям держаться поодаль.",
	["Megavolt hits a cone in front of it: only the tank should stand there. Interrupt its Chain Bolt."] = "«Мегавольт» бьёт в конусе перед собой: там должен стоять только танк. Прерывайте его «Цепную стрелу».",
	["Nothing special on the boss itself: clear the other spiders of the courtyard first, or they join the fight."] = "В самом боссе нет ничего особенного: сначала убейте остальных пауков во дворе, иначе они присоединятся к бою.",
	["Nothing special seen in the fight yet: he hits, and has a lot of health."] = "В бою пока ничего особенного: он бьёт и у него много здоровья.",
	["Once Kelris is dead, light the four Fires of Aku'mai one after another; each brings a wave, and the door opens when all are dead."] = "Когда Келрис мёртв, зажгите четыре Огня Аку'мая один за другим; каждый приводит волну, а когда все мертвы, дверь открывается.",
	["One of the four Fanglords; killing all four lets the Disciple of Naralex begin the ritual."] = "Один из четырёх Повелителей Клыка; убийство всех четырёх позволяет Ученику Наралекса начать ритуал.",
	["Only the Fel Steed stomps: a 3-second stun, and more physical damage taken."] = "Топает только Конь Скверны: оглушение на 3 секунды и больше получаемого физического урона.",
	["Past Atrexis, clear the north-east room with the market stalls and the small pink summoning circle. Whoever carries the tome clicks the circle, and Lyn comes out of the big round grate."] = "За Атрексисом зачистите северо-восточную комнату с рыночными прилавками и маленьким розовым кругом призыва. Тот, у кого есть фолиант, нажимает на круг, и Лин выходит из большой круглой решётки.",
	["Poison Cloud hurts everyone nearby, and below 30% health he attacks much faster."] = "«Облако яда» бьёт всех поблизости, а ниже 30% здоровья он атакует гораздо быстрее.",
	["Raises skeletons through the fight: kill them, and give the tank time to build threat before using area damage."] = "Поднимает скелетов на протяжении боя: убивайте их и дайте танку время набрать угрозу, прежде чем бить по площади.",
	["Remove his Veil of Shadow, above all from the tank: healing on them is much weaker."] = "Снимайте его «Покров тени», прежде всего с танка: исцеление на нём гораздо слабее.",
	["Shadow Bolt Volley and Curse of Thorns together hurt: remove the curse, melee above all. She raises skeletons as Atrexis does."] = "«Залп стрел Тьмы» и «Проклятие шипов» вместе больно бьют: снимите проклятие, прежде всего с ближнего боя. Она поднимает скелетов, как и Атрексис.",
	["She appears at one of four places. Interrupt her Healing Touch; damage or a magic dispel wakes a sleeping player, and her Thorns Aura hurts melee."] = "Она появляется в одном из четырёх мест. Прерывайте её «Целебное прикосновение»; урон или магическое рассеивание будит спящего игрока, а её «Аура шипов» ранит ближний бой.",
	["Shell Shield: for 12 seconds he takes much less damage, and hits slower but harder."] = "«Панцирный щит»: 12 секунд он получает гораздо меньше урона, а бьёт медленнее, но сильнее.",
	["Shield Slam stuns the tank; at 15% health he runs for help."] = "«Удар щитом» оглушает танка; на 15% здоровья он убегает за помощью.",
	["Skyborne only"] = "только для Небожителей",
	["Small raptors leap out of the grass as you walk through it, and make you bleed."] = "Маленькие ящеры выпрыгивают из травы, когда вы идёте по ней, и вызывают кровотечение.",
	["Sneed fights from inside the shredder, and climbs out when it is destroyed."] = "Снид сражается изнутри дробилки и выбирается наружу, когда её уничтожают.",
	["Speak to Blastmaster Emi Shortfuse and protect her while she seals the two cave mouths: troggs come in waves, then Grubbis with Chomper."] = "Поговорите с подрывницей Эми Короткий Фитиль и защищайте её, пока она заделывает два входа в пещеры: трогги идут волнами, затем приходит Граббис с Хрумом.",
	["Stay on the platform: small adds wait at the room's edge."] = "Держитесь на платформе: мелкая подмога ждёт у края комнаты.",
	["Stay out of her Forked Lightning cone. Frost Nova freezes everyone near her, and she slows a player."] = "Держитесь вне конуса её «Разветвлённой молнии». «Кольцо льда» замораживает всех рядом с ней, и она замедляет одного игрока.",
	["Step out of his Flame Spike. A magic dispel removes Flame Shock; interrupt his Shadow Bolt. Fire Nova burns those close to him."] = "Выйдите из его «Огненного шипа». Магическое рассеивание снимает «Огненный шок»; прерывайте его «Стрелу Тьмы». «Огненная вспышка» жжёт всех рядом.",
	["Steps out of his shredder once it breaks."] = "Выбирается из своей дробилки, когда она ломается.",
	["Stomps at 75% and again at 50% health, stunning the whole party. It cannot be interrupted."] = "Топает на 75%, а затем на 50% здоровья, оглушая всю группу. Это нельзя прервать.",
	["Stormwind"] = "Штормград",
	["Stuns, and calls his guards in when his health runs low."] = "Оглушает и призывает свою стражу, когда у него остаётся мало здоровья.",
	["Summoned by Archmage Arugal during his fight."] = "Призван архимагом Аругалом во время его боя.",
	["The braziers of the sanctum open the way to Aku'mai; each one lit calls a wave of enemies, so rest between them."] = "Жаровни святилища открывают путь к Аку'маю; каждая зажжённая призывает волну врагов, так что отдыхайте между ними.",
	["The hydra at the end of the Deeps, and the hardest fight here: keep a steady tank and healer on it."] = "Гидра в конце Пучины — самый тяжёлый бой здесь: держите ровного танка и лекаря.",
	["The Kraul's leader, at the end of the thorn maze."] = "Вожак лабиринта, в конце тернистого лабиринта.",
	["The last boss stands still at the end of the spider trail: click the small panel beside him to wake him."] = "Последний босс неподвижно стоит в конце паучьей тропы: нажмите на маленькую панель рядом с ним, чтобы разбудить его.",
	["The last boss: Archmage Modera opens the Portal to the Violet Chamber, which leads to him."] = "Последний босс: архимаг Модера открывает портал в Фиолетовую палату, который ведёт к нему.",
	["The last Fanglord, a plain melee fighter with fewer hit points than Pythas."] = "Последний Повелитель Клыка — простой боец ближнего боя с меньшим запасом здоровья, чем у Пифаса.",
	["The longer the fight, the more worgs join him: kill him quickly."] = "Чем дольше бой, тем больше воргов к нему прибегает: убивайте его быстро.",
	["The longest fight of the dungeon: a large health pool, so keep the interrupts going."] = "Самый долгий бой в подземелье: большой запас здоровья, так что не прекращайте прерывания.",
	["The prison is tight: a fleeing player can easily run into another cell block and bring it along."] = "Тюрьма тесная: убегающий игрок легко влетит в другой блок камер и приведёт его с собой.",
	["The ringleader of the uprising, found in one of three places."] = "Главарь бунта, которого можно найти в одном из трёх мест.",
	["The ship's cook, found aboard the juggernaut."] = "Корабельный кок, которого можно найти на дредноуте.",
	["The shredder ignores burning, bleeding and stun-style concussion effects."] = "Дробилка игнорирует горение, кровотечение и оглушающие эффекты.",
	["The toughest Fanglord, with heavy melee and a large health pool."] = "Самый крепкий Повелитель Клыка: тяжёлый ближний бой и большой запас здоровья.",
	["Thundercrack stuns everyone near him; he also puts players to sleep and fears them."] = "«Раскат грома» оглушает всех рядом; он также усыпляет игроков и пугает их.",
	["Two Mana Phantoms fight beside him: kill them first, their Mana Burn drains whoever they target."] = "Два манапризрака сражаются рядом с ним: убейте их первыми, их «Сжигание маны» вытягивает ману у цели.",
	["Waits at the top of the keep and calls a Voidwalker to his side."] = "Ждёт на вершине крепости и призывает к себе стража Бездны.",
	["Waits in the captain's cabin at the top of the ship."] = "Ждёт в капитанской каюте наверху корабля.",
	["When he dies, twenty Scarlet Trainees rush in through the hall's door: stay together and use area damage."] = "Когда он умирает, двадцать новобранцев Алого ордена врываются в дверь зала: держитесь вместе и используйте урон по площади.",
	["When his mana runs dry he turns the whole group into animals for 8 seconds, then channels Evocation to refill it. Casters can hide behind the wall from the polymorph, but if anyone leaves the room he resets to full health."] = "Когда у него кончается мана, он превращает всю группу в животных на 8 секунд, затем поддерживает «Призыв», чтобы восполнить её. Заклинатели могут спрятаться от превращения за стеной, но если кто-то покинет комнату, он сбрасывается на полное здоровье.",
	["When his target is close he knocks down and roots everyone near him: ranged players, keep your distance."] = "Когда его цель рядом, он сбивает с ног и обездвиживает всех возле себя: стрелкам держать дистанцию.",
	["When Mograine falls he is only playing dead: she runs out of the room behind the altar."] = "Когда Могрейн падает, он лишь притворяется мёртвым: она выбегает из комнаты за алтарём.",
	["When pulled he calls every Scarlet defender within 80 yards: clear the cathedral first."] = "При пуле он созывает всех защитников Алого ордена в радиусе 80 метров: сначала зачистите собор.",
	["When pulled he calls everything within 30 yards: clear around him first. He hits harder at 60%, 40% and 20% health."] = "При пуле он созывает всех в радиусе 30 метров: сначала зачистите вокруг него. На 60%, 40% и 20% здоровья он бьёт сильнее.",
	["With all four Fanglords dead, speak to the Disciple of Naralex at the entrance and escort him to Naralex."] = "Когда все четыре Повелителя Клыка мертвы, поговорите с Учеником Наралекса у входа и проводите его к Наралексу.",
	["With two axes he strikes the tank extra times; with the hammer, below 33%, he stuns the tank."] = "С двумя топорами он наносит танку дополнительные удары; с молотом, ниже 33%, он оглушает танка.",
	["Zephras Isle"] = "Остров Зефрас",
